-- ===== Catalog census =====
select is(
  (select count(*)::int from pg_proc p where p.pronamespace = 'public'::regnamespace and has_function_privilege('anon', p.oid, 'EXECUTE')),
  0, 'census: anon (incl. PUBLIC) can EXECUTE no function in schema public');

-- G-13: a named allowlist of signatures, not a count. A new browser-callable function must be added here on purpose.
select set_eq(
  $q$select format('%s(%s)', p.proname, oidvectortypes(p.proargtypes)) from pg_proc p where p.pronamespace = 'public'::regnamespace and has_function_privilege('authenticated', p.oid, 'EXECUTE')$q$,
  $q$values ('is_active_member(text[])'), ('is_active_member_mfa(text[])'), ('job_status_summary()'), ('usage_daily_summary(date, date)'), ('knowledge_gaps(date, date, integer)'),
    ('admin_register_document(uuid, text, text, bigint, text)'), ('admin_add_document_version(uuid, text, bigint)'), ('admin_complete_upload(uuid)'), ('admin_retry_version(uuid)'),
    ('admin_reindex_document(uuid)'), ('admin_document_status(uuid, integer, integer)'), ('admin_request_download(uuid)'), ('admin_delete_document(uuid)'),
    ('admin_list_bots()'), ('admin_get_settings(uuid)'), ('admin_update_settings(uuid, integer, jsonb)'), ('admin_set_bot_enabled(uuid, integer, boolean)'),
    ('admin_delete_conversation(uuid)'), ('admin_list_members()'), ('schema_version()')$q$,
  'census: authenticated can EXECUTE exactly the named allowlist of signatures (membership probes, three safe RPCs, eight P3.5 document RPCs, seven P3.5 settings RPCs)');

select is(
  (select count(*)::int from pg_proc p, lateral aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
    where p.pronamespace = 'public'::regnamespace and a.grantee = 0 and a.privilege_type = 'EXECUTE'),
  0, 'census: no function in schema public is executable by PUBLIC');

