  $q$select format('%s(%s)', p.proname, oidvectortypes(p.proargtypes)) from pg_proc p where p.pronamespace = 'public'::regnamespace and p.prosecdef$q$,
  $q$values ('is_active_member(text[])'), ('is_active_member_mfa(text[])'), ('job_status_summary()'), ('usage_daily_summary(date, date)'), ('knowledge_gaps(date, date, integer)'),
    ('admin_register_document(uuid, text, text, bigint, text)'), ('admin_add_document_version(uuid, text, bigint)'), ('admin_complete_upload(uuid)'), ('admin_retry_version(uuid)'),
