    ('admin_list_bots()'), ('admin_get_settings(uuid)'), ('admin_update_settings(uuid, integer, jsonb)'), ('admin_set_bot_enabled(uuid, integer, boolean)'),
    ('admin_delete_conversation(uuid)'), ('admin_list_members()')$q$,
  'census: SECURITY DEFINER functions are exactly the named allowlist (the authenticated allowlist minus schema_version, which is SECURITY INVOKER)');
select ok((select not prosecdef from pg_proc where pronamespace = 'public'::regnamespace and proname = 'schema_version'), 'census: schema_version is SECURITY INVOKER (it reads no table)');

select is(
  (select count(*)::int from pg_proc p where p.pronamespace = 'public'::regnamespace
     and not exists (select 1 from unnest(coalesce(p.proconfig, '{}')) c where c like 'search_path=%')),
  0, 'census: every function in schema public pins search_path');

