select is(
  (select count(*)::int from pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind in ('r', 'p') and not c.relrowsecurity),
  0, 'census: RLS is enabled on every table in schema public');

select is(
  (select count(*)::int from pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind in ('v', 'm')),
  0, 'census: no views/materialized views in schema public (nothing to wrap as security_invoker)');

select set_eq(
  $q$select distinct table_name::text from information_schema.role_table_grants where grantee = 'anon' and table_schema = 'public'$q$,
  $q$values ('public_bot_config')$q$,
  'census: anon has table privileges on public_bot_config ONLY');

select set_eq(
  $q$select privilege_type::text from information_schema.role_table_grants where grantee = 'anon' and table_schema = 'public'$q$,
  $q$values ('SELECT')$q$,
  'census: anon privilege on public_bot_config is SELECT only');

select is(
  (select count(*)::int from information_schema.role_table_grants
    where grantee = 'authenticated' and table_schema = 'public' and privilege_type <> 'SELECT'),
  0, 'census: authenticated has no INSERT/UPDATE/DELETE/TRUNCATE/REFERENCES/TRIGGER on any public table');

select set_eq(
  $q$select distinct table_name::text from information_schema.role_table_grants where grantee = 'authenticated' and table_schema = 'public'$q$,
  $q$values ('public_bot_config'), ('documents'), ('document_versions'), ('conversations'), ('messages'), ('message_sources'), ('conversation_analysis'), ('data_entries'), ('audit_logs')$q$,
  'census: authenticated SELECT grants are exactly the matrix-permitted relations');

select is(
  (select count(*)::int from information_schema.role_usage_grants where grantee in ('anon', 'authenticated') and object_schema = 'public'),
  0, 'census: anon/authenticated hold no sequence/other usage grants in public');

select is(
  (select count(*)::int from pg_default_acl d, lateral aclexplode(d.defaclacl) a
    where d.defaclnamespace = 'public'::regnamespace and d.defaclrole = (select oid from pg_roles where rolname = 'postgres') and a.grantee in (select oid from pg_roles where rolname in ('anon', 'authenticated'))),
  0, 'census: no default privileges for anon/authenticated remain for objects created by postgres (migration owner) in schema public');

-- ---- P3-D1 census additions ----
-- L6: the three admin RPCs authorise via auth.uid(); service_role has no business executing them.
select ok(
  not has_function_privilege('service_role', 'public.job_status_summary()', 'EXECUTE')
  and not has_function_privilege('service_role', 'public.usage_daily_summary(date, date)', 'EXECUTE')
  and not has_function_privilege('service_role', 'public.knowledge_gaps(date, date, integer)', 'EXECUTE')
  and not has_function_privilege('service_role', 'public.is_active_member_mfa(text[])', 'EXECUTE'),
  'census (L6): service_role cannot EXECUTE the three admin RPCs or is_active_member_mfa');
select ok(
  has_function_privilege('authenticated', 'public.job_status_summary()', 'EXECUTE')
  and has_function_privilege('authenticated', 'public.usage_daily_summary(date, date)', 'EXECUTE')
  and has_function_privilege('authenticated', 'public.knowledge_gaps(date, date, integer)', 'EXECUTE')
  and has_function_privilege('authenticated', 'public.is_active_member_mfa(text[])', 'EXECUTE'),
  'census (L6): authenticated can still EXECUTE the three admin RPCs and is_active_member_mfa');

