-- Table privileges: nothing is granted to PUBLIC (grantee 0) on any relation in schema public.
select is(
  (select count(*)::int
     from pg_class c, lateral aclexplode(coalesce(c.relacl, acldefault('r', c.relowner))) a
    where c.relnamespace = 'public'::regnamespace and c.relkind in ('r', 'p', 'v', 'm', 'S') and a.grantee = 0),
  0, 'census: PUBLIC holds no privilege on any relation in schema public');

-- Column-level privileges: anon/authenticated hold NO column-specific grant (attacl) anywhere ...
select is(
  (select count(*)::int
     from pg_attribute at
     join pg_class c on c.oid = at.attrelid
     cross join lateral aclexplode(at.attacl) a
    where c.relnamespace = 'public'::regnamespace and at.attacl is not null
      and a.grantee in (select oid from pg_roles where rolname in ('anon', 'authenticated') union select 0::oid)),
  0, 'census: no column-level grants (pg_attribute.attacl) for anon, authenticated or PUBLIC in schema public');

-- ... and the effective column privileges equal the table grants: anon SELECT public_bot_config only.
select set_eq(
  $q$select distinct table_name::text from information_schema.column_privileges where grantee = 'anon' and table_schema = 'public'$q$,
  $q$values ('public_bot_config')$q$,
  'census: anon column privileges exist on public_bot_config only');
select is(
  (select count(*)::int from information_schema.column_privileges
    where grantee in ('anon', 'authenticated') and table_schema = 'public' and privilege_type <> 'SELECT'),
  0, 'census: anon/authenticated column privileges are SELECT only');
select set_eq(
  $q$select distinct table_name::text from information_schema.column_privileges where grantee = 'authenticated' and table_schema = 'public'$q$,
  $q$values ('public_bot_config'), ('documents'), ('document_versions'), ('conversations'), ('messages'), ('message_sources'), ('conversation_analysis'), ('data_entries'), ('audit_logs')$q$,
  'census: authenticated column privileges exist only on the matrix-permitted relations');

-- pgvector must be >= 0.8.0 (iterative index scans used by match_document_chunks).
select ok(
  (select string_to_array(extversion, '.')::int[] >= array[0, 8, 0] from pg_extension where extname = 'vector'),
  'census: pgvector extension version >= 0.8.0');

-- L1: service_role holds exactly SELECT + INSERT on audit_logs.
select set_eq(
  $q$select privilege_type::text from information_schema.role_table_grants where grantee = 'service_role' and table_schema = 'public' and table_name = 'audit_logs'$q$,
  $q$values ('SELECT'), ('INSERT')$q$,
  'census (L1): service_role holds only SELECT and INSERT on audit_logs');

-- Foreign-key index coverage: every FK has an index whose leading columns are the FK columns.
select is(
  (select count(*)::int
     from pg_constraint c
    where c.contype = 'f' and c.connamespace = 'public'::regnamespace
      and not exists (
        select 1 from pg_index i
         where i.indrelid = c.conrelid
           and i.indisvalid
           and (select array_agg(k order by k) from unnest((i.indkey::int2[])[0:cardinality(c.conkey) - 1]) k)
               = (select array_agg(k order by k) from unnest(c.conkey) k)
      )),
  0, 'census: every foreign key is covered by an index');

-- C-6: the guard comes first. Every browser admin RPC must start (after `begin`, comments stripped) with
-- `perform public.admin_require(`, so no statement can run before the caller is checked. schema_version has no
-- prefix `admin_` and takes no guard. The predicate is checked on sample bodies first, so the census can fail.
create function pg_temp.first_stmt_is_guard(p_src text) returns boolean language sql immutable as $f$
  select regexp_replace(
           regexp_replace(regexp_replace(p_src, '/\*.*?\*/', '', 'g'), '--[^\n]*', '', 'g'),
           '^.*?\mbegin\M', '') ~ '^\s*perform\s+public\.admin_require\(';
$f$;
select ok(pg_temp.first_stmt_is_guard(E'#variable_conflict use_column\ndeclare\n  v int;\nbegin\n  -- the guard\n  perform public.admin_require(array[''owner'']);\n  perform 1;\nend;'), 'census (C-6) predicate: a body that starts with the guard passes (declare section, comment, conflict directive)');
select ok(not pg_temp.first_stmt_is_guard(E'begin\n  perform 1;\n  perform public.admin_require(array[''owner'']);\nend;'), 'census (C-6) predicate: a statement before the guard fails');
select ok(not pg_temp.first_stmt_is_guard(E'begin\n  -- perform public.admin_require(array[''owner'']);\n  perform 1;\nend;'), 'census (C-6) predicate: a guard that is only in a line comment fails');
select ok(not pg_temp.first_stmt_is_guard(E'begin\n  /* perform public.admin_require(array[''owner'']); */\n  perform 1;\nend;'), 'census (C-6) predicate: a guard that is only in a block comment fails');
select ok(not pg_temp.first_stmt_is_guard(E'begin\n  if true then perform public.admin_require(array[''owner'']); end if;\n  perform 1;\nend;'), 'census (C-6) predicate: a guard inside a conditional fails');
select ok(not pg_temp.first_stmt_is_guard(E'begin\n  perform admin_require(array[''owner'']);\nend;'), 'census (C-6) predicate: an unqualified guard name fails');
select ok(not pg_temp.first_stmt_is_guard(E'begin\n  select public.admin_require(array[''owner'']);\nend;'), 'census (C-6) predicate: a select instead of perform fails');
select is(
  (select count(*)::int from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname like 'admin\_%' and has_function_privilege('authenticated', p.oid, 'EXECUTE')),
  14, 'census (C-6): there are 14 browser admin RPCs (executable by authenticated, named admin_*)');
select is(
  (select array_agg(p.proname order by p.proname) from pg_proc p
    where p.pronamespace = 'public'::regnamespace and p.proname like 'admin\_%' and has_function_privilege('authenticated', p.oid, 'EXECUTE')
      and not pg_temp.first_stmt_is_guard(p.prosrc)),
  null::name[], 'census (C-6): the first statement of every browser admin RPC is perform public.admin_require(');

select * from finish();
rollback;
